class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if self.rank[rootX] > self.rank[rootY]:
                self.parent[rootY] = rootX
            elif self.rank[rootX] < self.rank[rootY]:
                self.parent[rootX] = rootY
            else:
                self.parent[rootY] = rootX
                self.rank[rootX] += 1

def prime_factors(n):
    factors = set()
    # Check for number of 2s that divide n
    while n % 2 == 0:
        factors.add(2)
        n //= 2
    # n must be odd at this point, so a skip of 2 (i.e., i = i + 2) can be used
    for i in range(3, int(n**0.5) + 1, 2):
        # While i divides n, add i and divide n
        while n % i == 0:
            factors.add(i)
            n //= i
    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        factors.add(n)
    return factors

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        if len(nums) == 1:
            return True

        # If there's a 1 in the array, we cannot traverse to it from any other number
        if 1 in nums:
            return False

        uf = UnionFind(len(nums))

        for i, num in enumerate(nums):
            factors = prime_factors(num)
            first_factor = None
            for factor in factors:
                if first_factor is None:
                    first_factor = factor
                else:
                    uf.union(i, nums.index(first_factor))

        # Check if all numbers are in the same connected component
        root = uf.find(0)
        for i in range(1, len(nums)):
            if uf.find(i) != root:
                return False

        return True

